mapper.select:
select sd.D_ID, sd.D_Name, sd.D_Code, sd.D_ParentID, sd.D_Type, sd.D_MDM_NO, sd.D_Company_Id, sd.D_Solution, sp.P_Name, sp.P_Code, sp.P_MDM_NO, sr.Role_Name, sr.Role_Code, sr.Role_Type, spu.U_ID from SYS_Department sd left join SYS_Position sp on sd.D_ID = sp.D_ID left join SYS_Position_User spu on spu.P_ID = sp.P_ID left join SYS_Position_Role spr on spr.P_ID = sp.P_ID left join SYS_Role sr on sr.Role_ID = spr.Role_ID
where spu.U_ID in
#{uId}

select sr.Role_Name, sr.Role_Code, sr.Role_Type, spp.PP_Name, spp.PP_Code, spp.PP_MDM_NO, sdp.PD_Name, sdp.PD_Code, sdp.PD_ParentID, sdp.PD_Type, sdp.PD_ID, sdp.P_ID, sdp.PD_MDM_NO, spup.U_ID from SYS_Position_User_P spup left join SYS_Position_P spp on spup.PP_ID = spp.PP_ID left join SYS_Department_P sdp on sdp.PD_ID = spp.PD_ID left join SYS_PositionP_Role sppr on sppr.PP_ID = spp.PP_ID left join SYS_Role sr on sr.Role_ID = sppr.Role_ID
where spup.U_ID in
#{uId}

select spup1.U_ID,sdp1.P_ID,su.C_ID,spp1.PP_Name from SYS_Position_P spp1 left join SYS_Position_User_P spup1 on spp1.PP_ID=spup1.PP_ID left join SYS_Department_P sdp1 on sdp1.PD_ID=spp1.PD_ID left join Sys_User su on su.U_ID=spup1.U_ID where sdp1.P_ID in( SELECT sdp.P_ID FROM SYS_Position_P spp left join SYS_Position_User_P spup on spp.PP_ID=spup.PP_ID left join SYS_Department_P sdp on sdp.PD_ID=spp.PD_ID where su.U_State='1' and su.U_Type!='2'
and spup.U_ID in
#{userId}
and sdp.P_ID in
#{pId}
)
and spp1.PP_Name in
#{pName}
